module pll_4x(  
    input clk_in,  
    input reset,  
    input enable,  
    output reg clk_out  
);  
    reg [1:0] counter;  

    always @(posedge clk_in or posedge reset) begin  
        if (reset) begin  
            counter <= 2'b00;  
            clk_out <= 1'b0;  
        end else if (enable) begin  
            counter <= counter + 1;  
            if (counter == 2'b11) begin  
                clk_out <= ~clk_out;  
                counter <= 2'b00;  
            end  
        end  
    end  
endmodule

